# -*- coding: utf-8 -*-
# Обновление системного промта kip8test до post-Task 312
# («+ Отпуск» в карточку, попап без «— выходной —» и кодов
#  мероприятий, цвет «.» — белый #FAF9F5)
with open('Системный_промт_для_приложения_КИПиА.md', encoding='utf-8') as f:
    lines = f.readlines()

new3 = '''> **Версия документа:** 2026-09-04 (post-Task 312: «+ ОТПУСК» ИЗ ТУЛБАРА → КАРТОЧКА СОТРУДНИКА + ПОПАП ЯЧЕЙКИ БЕЗ «— ВЫХОДНОЙ —» И БЕЗ КОДОВ МЕРОПРИЯТИЙ + ЦВЕТ «.» — БЕЛЫЙ #FAF9F5. Заявка пользователя: «В разделе "График работы", в баре над шахматкой убери кнопку "+ Отпуск", а её функционал перемести в новую кнопку в окно сотрудника в блок отпуска. В открывающимся окне ячеек шахматки коды которые добавляются через "+ Мероприятия" убери из списка основных, они будут добавляться только в виде маленьких иконок в ячейках. В этом же окне убери самый первый код, которого нет в таблице кодов " — выходной", а цвет кода "." нужно сделать белым как в пустых ячейках с точкой (напишешь мне код цвета, я заменю на него в таблице)». СОДЕРЖАНИЕ: 1) КНОПКА: #wsVacBtn и .ws-addvac-btn (HTML + CSS тёмная/светлая + правило высоты 34px) УДАЛЕНЫ, init() больше не управляет видимостью; в _renderEmpPopup (блок «Отпуска · год», после списка периодов) рендерится строка-действие «+ Отпуск…» (.ws-popup-row.ws-popup-more.ws-emp-addvac — стиль как «+ Мероприятие…») ТОЛЬКО редакторам; НОВЫЙ onEmpAddVacation(tabNo) — closeEmpPopup → openVacationForm(tabNo); openVacationForm принимает НЕОБЯЗАТЕЛЬНЫЙ таб.№: сотрудник карточки выбирается в списке шторки ДО onVacEmployeeChange (часть 1–3/лимит 42 дн. Task 310 сразу его); двойная защита _canEdit не снята; шторка #wsVacSheet без изменений. 2) ПОПАП ЯЧЕЙКИ (_renderCellPopup): строка «— выходной —» (код «—», нет в «Коды_статусов») + .ws-popup-swatch-empty УДАЛЕНЫ (очистка — «Дополнительно…»: select «— выходной —» + удаление; семантика _applyCellStatus(«»)/__delete жива); коды мероприятий _EVENT_CODES (И/ОБ/ПЗ/ПР/*) исключены из списка основных — добавляются «+ Мероприятие…» (Task 303) и живут бейджами; день-событие без смены (generateMonth пишет И/ОБ/ПЗ основным кодом) в попапе не подсвечен строкой, событие — в секции ниже; select «Статус» шита (_fillStatusSelect): мероприятия не предлагаются к ВЫБОРУ, ТЕКУЩЕЕ значение-мероприятие остаётся опцией (шит не «теряет» статус). 3) ЦВЕТ «.»: код цвета для листа «Коды_статусов» — #FAF9F5 (точный фон пустых ячеек с точкой, светлая тема --bg-primary; пользователь меняет в листе сам); fallback клиента синхронизирован #CFD8DC→#FAF9F5; в тёмной теме пустые ячейки #1a2233, лист хранит ОДИН цвет — «.»-ячейки светлые в обеих темах (выбор пользователя). Тесты: 1511 → 1528/0 (+17 test-task312.js; актуализированы task311/work-schedule; SW-бамп v550→v551 в 10 тест-файлах). Верификация: task312-browser-check.py 31/31 (3 контекста, порт 8937); регресс task298 33/33, 303 20/20, 304 10/10, 305 20/20, 306 29/29, 307 20/20, 308 20/20, 309 26/26, 310 20/20, 311 24/24 (актуализированы под Task 312); VLM ×5. СЕРВЕР и листы НЕ менялись. ПЕРЕНОС В kip8: НЕ выполнен (ожидает проверки пользователем в kip8test; следующий шаг — Task 312-перенос). Деплой пользователя: GitHub Pages + Ctrl+Shift+R ×1–2; Apps Script НЕ трогать; в листе «Коды_статусов» заменить цвет «.» на #FAF9F5.)
'''

assert lines[2].startswith('> **Версия документа:**')
lines.insert(2, new3 if new3.endswith('\n') else new3 + '\n')
prev = [i for i, l in enumerate(lines[:40]) if l.startswith('> **Версия документа (предыдущая):**')]
while len(prev) > 12:
    del lines[prev[-1]]
    prev = [i for i, l in enumerate(lines[:40]) if l.startswith('> **Версия документа (предыдущая):**')]
print('Строка 3 вставлена; цепочка «предыдущих»:', len(prev))

src = ''.join(lines)

reps = [
    ('> **Текущая версия кэша:** `kipia-test-v548`',
     '> **Текущая версия кэша:** `kipia-test-v551`'),
    ('| `kip8test` | PWA | `kipia-test-v550` |',
     '| `kip8test` | PWA | `kipia-test-v551` |'),
]
for old, new in reps:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Версии кэша обновлены (2 замены)')

# Счётчики тестов (ранее застряли на 1345/20)
reps2 = [
    ('├── tests/                      # 1345 юнит-тестов (Node.js, 20 файлов)',
     '├── tests/                      # 1528 юнит-тестов (Node.js, 30 файлов)'),
    ('ожидается `1345 passed, 0 failed`', 'ожидается `1528 passed, 0 failed`'),
    ('# Ожидается: 1345 passed, 0 failed', '# Ожидается: 1528 passed, 0 failed'),
]
for old, new in reps2:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Счётчики тестов обновлены (3 замены)')

# Аннотация Task 308: «+ Отпуск» из тулбара удалена (Task 312)
old308 = 'шторка #wsVacSheet — НОВАЯ кнопка «+ Отпуск» (#wsVacBtn .ws-addvac-btn) в ws-toolbar-main между «+ Сотрудник» (Task 307) и «Сформировать»'
new308 = 'шторка #wsVacSheet — Task 312: кнопка «+ Отпуск» из тулбара УДАЛЕНА, добавление — строкой «+ Отпуск…» в блоке отпусков карточки сотрудника (с префиллом таб.№; историческая справка Task 308: приносила #wsVacBtn .ws-addvac-btn в ws-toolbar-main между «+ Сотрудник» (Task 307) и «Сформировать»'
assert old308 in src
src = src.replace(old308, new308)
# закрыть скобку аннотации после «_vacYear (номер свободной части…»
old308b = '_loadVacations заполняет и _VAC_PAGE/_vacYear (номер свободной части + проверка пересечений в шторке; год плана = год шахматки)'
new308b = '_loadVacations заполняет и _VAC_PAGE/_vacYear (номер свободной части + проверка пересечений в шторке; год плана = год шахматки) — конец исторической справки)'
assert old308b in src
src = src.replace(old308b, new308b)
print('Аннотация Task 308 (кнопка в карточке) обновлена')

# Аннотация Task 251: строки «— выходной —» в попапе больше нет (Task 312)
old251 = 'свотч цвета + код + название, текущий статус подсвечен; строка «— выходной —»; «Дополнительно…» открывает прежний sheet'
new251 = 'свотч цвета + код + название, текущий статус подсвечен; Task 312: строка «— выходной —» УДАЛЕНА из попапа (очистка — в «Дополнительно…») и коды мероприятий не предлагаются (только статусы из листа); «Дополнительно…» открывает прежний sheet'
assert old251 in src
src = src.replace(old251, new251)
print('Аннотация Task 251 (попап без «выходного») обновлена')

entry = ('\n- **График работы — «+ Отпуск» в карточке сотрудника, попап ячейки без «— выходной —» и кодов мероприятий, цвет «.» белый (Task 312)**: '
         'по заявке пользователя: 1) КНОПКА «+ Отпуск» УДАЛЕНА из тулбара (#wsVacBtn, .ws-addvac-btn — HTML/CSS/правило 34px; init() не управляет) — функционал ПЕРЕЕХАЛ строкой «+ Отпуск…» (.ws-popup-row.ws-popup-more.ws-emp-addvac, стиль как «+ Мероприятие…») в блок «Отпуска · год» КАРТОЧКИ сотрудника (после списка периодов, до «Мероприятия»), ТОЛЬКО редакторам; клик: onEmpAddVacation(таб.№) → closeEmpPopup → openVacationForm(таб.№) — НОВЫЙ необязательный параметр: сотрудник карточки выбирается в списке шторки ДО onVacEmployeeChange, поэтому «часть» (первый свободный 1–3) и лимит года 42 дн. (Task 310) сразу считаются для него; двойная защита _canEdit в openVacationForm; шторка/лимит/блокировка — без изменений. '
         '2) ПОПАП ЯЧЕЙКИ: строка «— выходной —» (код «—» — нет в таблице «Коды_статусов») УДАЛЕНА вместе с пунктирным свотчем (.ws-popup-swatch-empty удалён из CSS); очистка ячейки — «Дополнительно…» (select «— выходной —» жив; семантика авто/руч/локальной правки — _applyCellStatus(\'\')/__delete — не менялась); КОДЫ МЕРОПРИЯТИЙ (_EVENT_CODES: И/ОБ/ПЗ/ПР/*) исключены из списка основных статусов — мероприятия добавляются ТОЛЬКО «+ Мероприятие…» (Task 303) и живут бейджами-«иконками» в ячейках; день-событие без смены (сервер generateMonth пишет И/ОБ/ПЗ основным кодом) в попапе не подсвечен строкой — событие видно в секции «Мероприятия в этот день» (с кнопками ✎/✕, Task 309); select «Статус» шита «Дополнительно…» (_fillStatusSelect): мероприятия не предлагаются к выбору, ТЕКУЩЕЕ значение-мероприятие остаётся опцией (иначе шит «терял» бы статус ячейки). '
         '3) ЦВЕТ «.» (Плановый выходной день): код для листа «Коды_статусов» — #FAF9F5 (точный фон пустых ячеек с точкой в светлой теме, --bg-primary; пользователь заменяет значение в листе сам); fallback клиента (офлайн) синхронизирован #CFD8DC→#FAF9F5; в тёмной теме пустые ячейки #1a2233, а лист хранит ОДИН цвет — «.»-ячейки светлые в обеих темах (осознанный выбор пользователя; код в ячейке и рамки не менялись). '
         'Сервер WorkSchedule.gs/листы/«Сформировать» — НЕ менялись; бейджи мероприятий и плановых смен (Task 303/305), рамка ручных д/н (Task 309/310) — живы. Верификация: сьют 1511→1528/0 (+17 tests/test-task312.js; актуализированы test-task311/test-work-schedule; v550→v551 в 10 тест-файлах), task312-browser-check.py 31/31 (порт 8937, 3 контекста; регресс 298 33/33, 303 20/20, 304 10/10, 305 20/20, 306 29/29, 307 20/20, 308 20/20, 309 26/26, 310 20/20, 311 24/24 — актуализированы), VLM ×5. SW kipia-test-v550→v551. '
         'ДЕПЛОЙ: только фронтенд — GitHub Pages + Ctrl+Shift+R ×1–2; Apps Script НЕ трогать; в листе «Коды_статусов» заменить цвет «.» на #FAF9F5 — см. scripts/DEPLOY-Task312-vac-in-card-popup-clean.md')
lines2 = src.split('\n')
insert_at = None
for i, l in enumerate(lines2):
    if l.startswith('- **График работы — карточка сотрудника, правка/удаление мероприятий'):
        j = i + 1
        while j < len(lines2) and lines2[j].startswith('  '):
            j += 1
        insert_at = j
        break
assert insert_at is not None, 'точка вставки (после записи Task 309) не найдена'
lines2.insert(insert_at, entry)
src = '\n'.join(lines2)

with open('Системный_промт_для_приложения_КИПиА.md', 'w', encoding='utf-8') as f:
    f.write(src)
print('Промт обновлён до post-Task 312: строка версии, цепочка, кэш v551, счётчики 1528/30, аннотации 251/308, буллет Task 312')
